arguments.file_text:
@page "/settings"
@rendermode InteractiveServer
@using sv_3f7184a0135f4c4c9191edb81d14701e.Models
@using sv_3f7184a0135f4c4c9191edb81d14701e.Services
@inject ISettingsService SettingsService

<PageTitle>Settings</PageTitle>

<h1 class="mb-4">Settings</h1>

@if (_loading)
{
    <div class="d-flex justify-content-center py-5">
        <div class="spinner-border" role="status">
            <span class="visually-hidden">Loading...</span>
        </div>
    </div>
}
else
{
    <!-- Toast notification -->
    @if (_toastVisible)
    {
        <div class="settings-toast @(_toastIsError ? "toast-error" : "")">
            @_toastMessage
        </div>
    }

    <div class="settings-layout">
        <!-- Left sidebar navigation -->
        <nav class="settings-sidebar">
            <ul class="nav flex-column">
                @foreach (var section in _sections)
                {
                    <li class="nav-item">
                        <button class="nav-link settings-nav-link @(_activeSection == section.Key ? "active" : "")"
                                @onclick="() => SetActiveSection(section.Key)">
                            <span class="settings-nav-icon">@section.Value.Icon</span>
                            @section.Value.Label
                        </button>
                    </li>
                }
            </ul>
        </nav>

        <!-- Main content area -->
        <div class="settings-content">
            @switch (_activeSection)
            {
                case "profile":
                    @RenderProfileSection()
                    break;
                case "notifications":
                    @RenderNotificationsSection()
                    break;
                case "security":
                    @RenderSecuritySection()
                    break;
                case "appearance":
                    @RenderAppearanceSection()
                    break;
            }
        </div>
    </div>
}

@* ───────── Profile Section ───────── *@

@{
    RenderFragment RenderProfileSection() =>
        @<div>
            <h3 class="mb-4">Profile</h3>

            <div class="d-flex align-items-center mb-4">
                <div class="avatar-preview me-3">
                    <img src="@_editProfile!.AvatarUrl" alt="Avatar" />
                </div>
                <div class="flex-grow-1">
                    <label class="form-label fw-semibold">Avatar URL</label>
                    <input type="url" class="form-control" @bind="_editProfile.AvatarUrl" />
                </div>
            </div>

            <div class="mb-3">
                <label class="form-label fw-semibold">Display Name</label>
                <input type="text" class="form-control" @bind="_editProfile.DisplayName" />
            </div>

            <div class="mb-3">
                <label class="form-label fw-semibold">Email</label>
                <input type="email" class="form-control" @bind="_editProfile.Email" />
            </div>

            <div class="mb-3">
                <label class="form-label fw-semibold">Bio</label>
                <textarea class="form-control" rows="4" @bind="_editProfile.Bio"></textarea>
            </div>

            <div class="d-flex gap-2">
                <button class="btn btn-primary" @onclick="SaveProfile" disabled="@_saving">
                    @if (_saving) { <span class="spinner-border spinner-border-sm me-1"></span> }
                    Save Changes
                </button>
                <button class="btn btn-outline-secondary" @onclick="DiscardProfileChanges">
                    Discard Changes
                </button>
            </div>
        </div>;
}

@* ───────── Notifications Section ───────── *@

@{
    RenderFragment RenderNotificationsSection() =>
        @<div>
            <h3 class="mb-4">Notifications</h3>

            <div class="mb-3">
                <div class="form-check form-switch mb-2">
                    <input class="form-check-input" type="checkbox" id="emailNotif"
                           checked="@_editNotifications!.EmailNotifications"
                           @onchange="e => _editNotifications.EmailNotifications = (bool)e.Value!" />
                    <label class="form-check-label" for="emailNotif">Email Notifications</label>
                </div>

                <div class="form-check form-switch mb-2">
                    <input class="form-check-input" type="checkbox" id="pushNotif"
                           checked="@_editNotifications.PushNotifications"
                           @onchange="e => _editNotifications.PushNotifications = (bool)e.Value!" />
                    <label class="form-check-label" for="pushNotif">Push Notifications</label>
                </div>

                <div class="form-check form-switch mb-2">
                    <input class="form-check-input" type="checkbox" id="weeklyDigest"
                           checked="@_editNotifications.WeeklyDigest"
                           @onchange="e => _editNotifications.WeeklyDigest = (bool)e.Value!" />
                    <label class="form-check-label" for="weeklyDigest">Weekly Digest</label>
                </div>
            </div>

            <h5 class="mt-4 mb-3">Muted Channels</h5>
            <div class="mb-4">
                @foreach (var channel in _allChannels)
                {
                    var isMuted = _editNotifications.MutedChannels.Contains(channel);
                    <div class="form-check mb-1">
                        <input class="form-check-input" type="checkbox" id="ch-@channel"
                               checked="@isMuted"
                               @onchange="e => ToggleMutedChannel(channel, (bool)e.Value!)" />
                        <label class="form-check-label" for="ch-@channel">
                            #@channel @(isMuted ? "(muted)" : "")
                        </label>
                    </div>
                }
            </div>

            <button class="btn btn-primary" @onclick="SaveNotifications" disabled="@_saving">
                @if (_saving) { <span class="spinner-border spinner-border-sm me-1"></span> }
                Save Preferences
            </button>
        </div>;
}

@* ───────── Security Section ───────── *@

@{
    RenderFragment RenderSecuritySection() =>
        @<div>
            <h3 class="mb-4">Security</h3>

            <!-- Change Password expandable panel -->
            <div class="card mb-4">
                <div class="card-header d-flex justify-content-between align-items-center"
                     style="cursor: pointer;" @onclick="() => _passwordPanelOpen = !_passwordPanelOpen">
                    <span class="fw-semibold">Change Password</span>
                    <span>@(_passwordPanelOpen ? "▲" : "▼")</span>
                </div>
                @if (_passwordPanelOpen)
                {
                    <div class="card-body">
                        <div class="mb-3">
                            <label class="form-label">Current Password</label>
                            <input type="password" class="form-control" @bind="_currentPassword" />
                        </div>
                        <div class="mb-3">
                            <label class="form-label">New Password</label>
                            <input type="password" class="form-control" @bind="_newPassword" />
                        </div>
                        <div class="mb-3">
                            <label class="form-label">Confirm New Password</label>
                            <input type="password" class="form-control" @bind="_confirmPassword" />
                        </div>
                        @if (!string.IsNullOrEmpty(_passwordError))
                        {
                            <div class="text-danger mb-2">@_passwordError</div>
                        }
                        <button class="btn btn-primary" @onclick="ChangePassword" disabled="@_saving">
                            @if (_saving) { <span class="spinner-border spinner-border-sm me-1"></span> }
                            Update Password
                        </button>
                    </div>
                }
            </div>

            <!-- Two-Factor Authentication -->
            <div class="card mb-4">
                <div class="card-body d-flex justify-content-between align-items-center">
                    <div>
                        <span class="fw-semibold">Two-Factor Authentication</span>
                        <span class="badge ms-2 @(_twoFactorEnabled ? "bg-success" : "bg-secondary")">
                            @(_twoFactorEnabled ? "Enabled" : "Disabled")
                        </span>
                    </div>
                    <div class="form-check form-switch mb-0">
                        <input class="form-check-input" type="checkbox"
                               checked="@_twoFactorEnabled"
                               @onchange="e => _twoFactorEnabled = (bool)e.Value!" />
                    </div>
                </div>
            </div>

            @if (_securitySettings!.LastPasswordChange.HasValue)
            {
                <p class="text-muted small">
                    Last password change: @_securitySettings.LastPasswordChange.Value.ToString("MMMM dd, yyyy")
                </p>
            }

            <!-- Active Sessions -->
            <h5 class="mt-4 mb-3">Active Sessions</h5>
            <div class="table-responsive">
                <table class="table table-hover">
                    <thead>
                        <tr>
                            <th>Device</th>
                            <th>Location</th>
                            <th>Last Active</th>
                            <th></th>
                        </tr>
                    </thead>
                    <tbody>
                        @foreach (var session in _securitySettings.Sessions)
                        {
                            var isCurrentSession = session.Id == _securitySettings.Sessions.First().Id;
                            <tr>
                                <td>@session.Device</td>
                                <td>@session.Location</td>
                                <td>@FormatLastActive(session.LastActive)</td>
                                <td>
                                    @if (isCurrentSession)
                                    {
                                        <span class="badge bg-info">Current</span>
                                    }
                                    else
                                    {
                                        <button class="btn btn-sm btn-outline-danger"
                                                @onclick="() => PromptRevokeSession(session)">
                                            Revoke
                                        </button>
                                    }
                                </td>
                            </tr>
                        }
                    </tbody>
                </table>
            </div>

            <!-- Revoke Confirmation Dialog -->
            @if (_sessionToRevoke is not null)
            {
                <div class="modal-backdrop-custom">
                    <div class="modal-dialog-custom">
                        <div class="card">
                            <div class="card-body">
                                <h5 class="card-title">Revoke Session</h5>
                                <p>Are you sure you want to revoke the session on <strong>@_sessionToRevoke.Device</strong> in @_sessionToRevoke.Location?</p>
                                <div class="d-flex gap-2 justify-content-end">
                                    <button class="btn btn-secondary" @onclick="() => _sessionToRevoke = null">Cancel</button>
                                    <button class="btn btn-danger" @onclick="ConfirmRevokeSession" disabled="@_saving">
                                        @if (_saving) { <span class="spinner-border spinner-border-sm me-1"></span> }
                                        Revoke
                                    </button>
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
            }
        </div>;
}

@* ───────── Appearance Section ───────── *@

@{
    RenderFragment RenderAppearanceSection() =>
        @<div>
            <h3 class="mb-4">Appearance</h3>

            <!-- Theme -->
            <div class="mb-4">
                <label class="form-label fw-semibold">Theme</label>
                <div>
                    @foreach (var theme in new[] { "Light", "Dark", "System" })
                    {
                        <div class="form-check form-check-inline">
                            <input class="form-check-input" type="radio" name="theme" id="theme-@theme"
                                   value="@theme"
                                   checked="@(_editAppearance!.Theme == theme)"
                                   @onchange="() => _editAppearance.Theme = theme" />
                            <label class="form-check-label" for="theme-@theme">@theme</label>
                        </div>
                    }
                </div>
            </div>

            <!-- Font Size -->
            <div class="mb-4">
                <label class="form-label fw-semibold">Font Size</label>
                <div>
                    @foreach (var size in new[] { "Small", "Medium", "Large" })
                    {
                        <div class="form-check form-check-inline">
                            <input class="form-check-input" type="radio" name="fontSize" id="fs-@size"
                                   value="@size"
                                   checked="@(_editAppearance!.FontSize == size)"
                                   @onchange="() => _editAppearance.FontSize = size" />
                            <label class="form-check-label" for="fs-@size">@size</label>
                        </div>
                    }
                </div>
            </div>

            <!-- Language -->
            <div class="mb-4">
                <label class="form-label fw-semibold">Language</label>
                <select class="form-select" @bind="_editAppearance!.Language">
                    @foreach (var lang in _languages)
                    {
                        <option value="@lang">@lang</option>
                    }
                </select>
            </div>

            <!-- Compact Mode -->
            <div class="mb-4">
                <div class="form-check form-switch">
                    <input class="form-check-input" type="checkbox" id="compactMode"
                           checked="@_editAppearance.CompactMode"
                           @onchange="e => _editAppearance.CompactMode = (bool)e.Value!" />
                    <label class="form-check-label" for="compactMode">Compact Mode</label>
                </div>
            </div>

            <!-- Live Preview -->
            <div class="mb-4">
                <label class="form-label fw-semibold">Preview</label>
                <div class="appearance-preview @GetPreviewClasses()">
                    <h5>Preview Area</h5>
                    <p>This is how your content will look with the selected settings.</p>
                    <button class="btn btn-sm @(_editAppearance.Theme == "Dark" ? "btn-light" : "btn-primary")">
                        Sample Button
                    </button>
                    <span class="ms-2 badge @(_editAppearance.Theme == "Dark" ? "bg-light text-dark" : "bg-secondary")">
                        Badge
                    </span>
                </div>
            </div>

            <button class="btn btn-primary" @onclick="SaveAppearance" disabled="@_saving">
                @if (_saving) { <span class="spinner-border spinner-border-sm me-1"></span> }
                Save
            </button>
        </div>;
}

@code {
    private readonly record struct SectionInfo(string Label, string Icon);

    private readonly Dictionary<string, SectionInfo> _sections = new()
    {
        ["profile"] = new("Profile", "👤"),
        ["notifications"] = new("Notifications", "🔔"),
        ["security"] = new("Security", "🔒"),
        ["appearance"] = new("Appearance", "🎨")
    };

    private readonly string[] _languages = ["English", "Spanish", "French", "German", "Japanese", "Portuguese", "Chinese"];
    private readonly string[] _allChannels = ["announcements", "random", "off-topic", "design", "engineering"];

    private string _activeSection = "profile";
    private bool _loading = true;
    private bool _saving;

    // Toast state
    private bool _toastVisible;
    private string _toastMessage = "";
    private bool _toastIsError;

    // Profile state
    private UserProfile? _savedProfile;
    private EditableProfile? _editProfile;

    // Notifications state
    private EditableNotifications? _editNotifications;

    // Security state
    private SecuritySettings? _securitySettings;
    private bool _twoFactorEnabled;
    private bool _passwordPanelOpen;
    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";
    private string _passwordError = "";
    private ActiveSession? _sessionToRevoke;

    // Appearance state
    private EditableAppearance? _editAppearance;

    protected override async Task OnInitializedAsync()
    {
        var profileTask = SettingsService.GetProfileAsync();
        var notifsTask = SettingsService.GetNotificationPrefsAsync();
        var securityTask = SettingsService.GetSecuritySettingsAsync();
        var appearanceTask = SettingsService.GetAppearanceAsync();

        await Task.WhenAll(profileTask, notifsTask, securityTask, appearanceTask);

        _savedProfile = profileTask.Result;
        _editProfile = EditableProfile.From(_savedProfile);

        var notifs = notifsTask.Result;
        _editNotifications = new EditableNotifications
        {
            EmailNotifications = notifs.EmailNotifications,
            PushNotifications = notifs.PushNotifications,
            WeeklyDigest = notifs.WeeklyDigest,
            MutedChannels = new List<string>(notifs.MutedChannels)
        };

        _securitySettings = securityTask.Result;
        _twoFactorEnabled = _securitySettings.TwoFactorEnabled;

        var appearance = appearanceTask.Result;
        _editAppearance = new EditableAppearance
        {
            Theme = appearance.Theme,
            FontSize = appearance.FontSize,
            Language = appearance.Language,
            CompactMode = appearance.CompactMode
        };

        _loading = false;
    }

    private void SetActiveSection(string section) => _activeSection = section;

    // ── Profile ──

    private async Task SaveProfile()
    {
        _saving = true;
        var profile = new UserProfile(_editProfile!.DisplayName, _editProfile.Email, _editProfile.AvatarUrl, _editProfile.Bio);
        await SettingsService.SaveProfileAsync(profile);
        _savedProfile = profile;
        _saving = false;
        await ShowToast("Profile saved successfully!");
    }

    private void DiscardProfileChanges()
    {
        _editProfile = EditableProfile.From(_savedProfile!);
    }

    // ── Notifications ──

    private void ToggleMutedChannel(string channel, bool isMuted)
    {
        if (isMuted && !_editNotifications!.MutedChannels.Contains(channel))
            _editNotifications.MutedChannels.Add(channel);
        else if (!isMuted)
            _editNotifications!.MutedChannels.Remove(channel);
    }

    private async Task SaveNotifications()
    {
        _saving = true;
        var prefs = new NotificationPrefs(
            _editNotifications!.EmailNotifications,
            _editNotifications.PushNotifications,
            _editNotifications.WeeklyDigest,
            new List<string>(_editNotifications.MutedChannels)
        );
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        _saving = false;
        await ShowToast("Notification preferences saved!");
    }

    // ── Security ──

    private async Task ChangePassword()
    {
        _passwordError = "";
        if (string.IsNullOrWhiteSpace(_currentPassword) || string.IsNullOrWhiteSpace(_newPassword))
        {
            _passwordError = "Please fill in all password fields.";
            return;
        }
        if (_newPassword != _confirmPassword)
        {
            _passwordError = "New password and confirmation do not match.";
            return;
        }
        if (_newPassword.Length < 8)
        {
            _passwordError = "New password must be at least 8 characters.";
            return;
        }

        _saving = true;
        await SettingsService.ChangePasswordAsync(_currentPassword, _newPassword);
        _securitySettings = await SettingsService.GetSecuritySettingsAsync();
        _currentPassword = "";
        _newPassword = "";
        _confirmPassword = "";
        _passwordPanelOpen = false;
        _saving = false;
        await ShowToast("Password updated successfully!");
    }

    private void PromptRevokeSession(ActiveSession session) => _sessionToRevoke = session;

    private async Task ConfirmRevokeSession()
    {
        _saving = true;
        await SettingsService.RevokeSessionAsync(_sessionToRevoke!.Id);
        _securitySettings = await SettingsService.GetSecuritySettingsAsync();
        _sessionToRevoke = null;
        _saving = false;
        await ShowToast("Session revoked.");
    }

    // ── Appearance ──

    private string GetPreviewClasses()
    {
        var classes = new List<string>();
        if (_editAppearance!.Theme == "Dark") classes.Add("preview-dark");
        else classes.Add("preview-light");
        classes.Add($"preview-font-{_editAppearance.FontSize.ToLowerInvariant()}");
        if (_editAppearance.CompactMode) classes.Add("preview-compact");
        return string.Join(" ", classes);
    }

    private async Task SaveAppearance()
    {
        _saving = true;
        var settings = new AppearanceSettings(
            _editAppearance!.Theme,
            _editAppearance.FontSize,
            _editAppearance.Language,
            _editAppearance.CompactMode
        );
        await SettingsService.SaveAppearanceAsync(settings);
        _saving = false;
        await ShowToast("Appearance settings saved!");
    }

    // ── Helpers ──

    private static string FormatLastActive(DateTime lastActive)
    {
        var diff = DateTime.UtcNow - lastActive;
        if (diff.TotalMinutes < 1) return "Just now";
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes}m ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours}h ago";
        return $"{(int)diff.TotalDays}d ago";
    }

    private async Task ShowToast(string message, bool isError = false)
    {
        _toastMessage = message;
        _toastIsError = isError;
        _toastVisible = true;
        StateHasChanged();
        await Task.Delay(3000);
        _toastVisible = false;
        StateHasChanged();
    }

    // ── Mutable wrapper classes for two-way binding ──

    private class EditableProfile
    {
        public string DisplayName { get; set; } = "";
        public string Email { get; set; } = "";
        public string AvatarUrl { get; set; } = "";
        public string Bio { get; set; } = "";

        public static EditableProfile From(UserProfile p) => new()
        {
            DisplayName = p.DisplayName,
            Email = p.Email,
            AvatarUrl = p.AvatarUrl,
            Bio = p.Bio
        };
    }

    private class EditableNotifications
    {
        public bool EmailNotifications { get; set; }
        public bool PushNotifications { get; set; }
        public bool WeeklyDigest { get; set; }
        public List<string> MutedChannels { get; set; } = new();
    }

    private class EditableAppearance
    {
        public string Theme { get; set; } = "Light";
        public string FontSize { get; set; } = "Medium";
        public string Language { get; set; } = "English";
        public bool CompactMode { get; set; }
    }
}

