    }

    .appearance-preview.preview-dark {
        background-color: #1e1e2e;
        color: #e0e0e0;
        border-color: #444;
    }

    .appearance-preview.preview-font-small {
        font-size: 0.8rem;
    }

    .appearance-preview.preview-font-medium {
