        font-size: 0.8rem;
    }

    .appearance-preview.preview-font-medium {
        font-size: 1rem;
    }

    .appearance-preview.preview-font-large {
        font-size: 1.2rem;
    }

    .appearance-preview.preview-compact {
        padding: 0.75rem;
        line-height: 1.3;
    }

        .appearance-preview.preview-compact h5 {
            margin-bottom: 0.25rem;
        }

        .appearance-preview.preview-compact p {
            margin-bottom: 0.5rem;
